mapper.select:
SELECT
    mtw.*,
    su.name AS reporter_name,
    mbtul.user_id AS team_leader_id,
    mbtul.user_name AS team_leader_name,
    mtwqc.name AS temp_work_quota_config_name,
    CONCAT(cp.serial_number, ' ', cp.short_name) AS project_name
FROM mes_temp_work mtw
LEFT JOIN mes_temp_work_quota_config mtwqc ON mtwqc.bool_delete_enum = 0 AND mtw.temp_work_quota_config_id = mtwqc.id
LEFT JOIN sys_user su ON su.bool_delete_enum = 0 AND mtw.reporter_id = su.id
LEFT JOIN mes_building_team_user_link mbtul ON mbtul.bool_delete_enum = 0 AND mbtul.team_id = mtw.team_id AND mbtul.bool_leader_enum = 1
LEFT JOIN contract_project cp ON cp.bool_delete_enum = 0 AND mtw.project_id = cp.id
WHERE mtw.bool_delete_enum = 0

    AND mtw.id = #{id}


    AND mtw.report_date >= #{startDate}


    AND mtw.report_date <= #{endDate}


    AND mtw.reporter_id = #{reporterId}


    AND mtw.approve_record_serial_number IN (
        SELECT DISTINCT approve_record_serial_number
        FROM wms_approve_record_detail
        WHERE bool_delete_enum = 0
        
            AND status = #{approveRecordDetailStatus}
        
        
            AND check_user_id = #{approverId}
        
    )


    AND mtw.approval_status IN
    
        #{item}
